"""Render the local experiment results; no source or database access."""
import html,json
from pathlib import Path

def esc(v):return html.escape(str(v if v is not None else 'Not provided'),quote=True)
def addr(a):return ', '.join(str(a[k]) for k in ('line1','line2','city','state','zip') if a.get(k)) if a else 'Not provided by the filing'
def render(path):
    data=json.loads((path/'results.json').read_text());s=data['summary'];results=data['results']
    # Useful account matches and follow-up leads first; original order remains in JSON/CSV.
    order={'PROBABLE_EXISTING_ACCOUNT':0,'ABANDONMENT_LEAD':1,'NEEDS_REVIEW':2,'NO_RELIABLE_MATCH':3}
    cards=[]
    for r in sorted(results,key=lambda r:(order[r['status']],r['record']['document_number'])):
        f=r['record'];p=r.get('production_match') or {};details=r.get('candidate_details') or r.get('matched_account_details') or {};candidates=r['name_only_candidates'];signals=p.get('signals') or {}
        candidate_text=''.join('<li><strong>'+esc(c['real_account_number'])+'</strong> · '+esc(c.get('owner_name'))+'<br>'+esc(c.get('situs_address_raw'))+'<br>Business / DBA: '+esc(c.get('business_name'))+' / '+esc(c.get('dba_name'))+'</li>' for c in candidates)
        paired=r.get('related_filings_in_sample',[])
        related=''.join('<li>'+esc(a['document_number'])+' · '+esc(a['filing_type'])+' · '+esc(' / '.join(a['owners']))+'</li>' for a in paired)
        evidence=''.join('<li>'+esc(k.replace('_',' '))+': '+esc(v)+'</li>' for k,v in signals.items() if k in ('address','zip','suite_unit','business_dba_name','legal_entity_name','personal_property_accounts'))
        status=r['status'].replace('_',' ').title();badge='good' if r['status']=='PROBABLE_EXISTING_ACCOUNT' else 'warn' if r['status']!='NO_RELIABLE_MATCH' else 'neutral'
        cards.append(f'''<article data-status="{esc(r['status'])}"><div class="row"><div><span class="eyebrow">{esc(f['document_number'])} · {esc(f['recording_date'])}</span><h2>{esc(f['assumed_name'])}</h2></div><span class="badge {badge}">{esc(status)} · {esc(r['confidence'])}</span></div><div class="grid"><section><h3>County filing</h3><p><strong>{esc(f['filing_type'])}</strong><br>Owners: {esc(' / '.join(f['owners']))}</p><p><b>Business address</b><br>{esc(addr(f['business_address']))}</p><p>Mailing: {esc(addr(f['mailing_address']))}<br>Expires: {esc(f['expiration_date'])}<br>Entity type: {esc(f['business_conducted_as'])}</p><a href="{esc(f['source_url'])}" target="_blank" rel="noopener noreferrer">Open original public record ↗</a></section><section><h3>Account comparison</h3><p class="account">{esc(r['matched_account'] or 'Needs account review')}</p>{('<p>'+esc(details.get('owner_name'))+'<br>'+esc(details.get('situs_address_raw'))+'<br>Business / DBA: '+esc(details.get('business_name'))+' / '+esc(details.get('dba_name'))+'</p>') if details else ''}<p>{esc(r['reason'])}</p>{('<ul>'+evidence+'</ul>') if evidence else ''}{('<details><summary>Name-based account suggestions ('+str(len(candidates))+')</summary><ul>'+candidate_text+'</ul></details>') if candidates else ''}{('<div class="note"><strong>Related filing in this sample</strong><ul>'+related+'</ul>Compare owner information before treating this as an opening or closure.</div>') if paired else ''}</section></div></article>''')
    counts=s['outcomes'];stats=[('Full details',s['details_retrieved']),('Full owner names',s['with_full_owners']),('Business addresses',s['with_business_address']),('Strong account leads',counts.get('PROBABLE_EXISTING_ACCOUNT',0)),('Other review leads',counts.get('NEEDS_REVIEW',0)+counts.get('ABANDONMENT_LEAD',0)),('No reliable match',counts.get('NO_RELIABLE_MATCH',0))]
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Lubbock DBA prototype results</title><style>
:root{--ink:#203438;--paper:#f7f3e9;--line:#dcd8cb;--green:#286452}*{box-sizing:border-box}body{margin:0;background:#eeeadd;color:var(--ink);font:16px/1.5 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:36px 24px}header{padding-bottom:24px}.eyebrow{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#657570}h1{font-size:36px;line-height:1.15;margin:10px 0 18px}h2{font-size:23px;margin:6px 0}h3{font-size:13px;text-transform:uppercase;letter-spacing:.05em;margin:12px 0;color:#586d66}p{margin:12px 0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:24px 0}.stat,article,.note{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:20px}.stat strong{display:block;font-size:32px}.stat span{font-size:14px;color:#596d65}.notice{background:#e1ece4;border-left:4px solid var(--green);padding:14px 18px;border-radius:5px}.row{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:36px}article{margin:18px 0}.badge{font-size:12px;border-radius:20px;padding:6px 10px;white-space:nowrap}.good{background:#d9e9dc}.warn{background:#f0e3be}.neutral{background:#e5e4dc}.account{font-size:26px;font-weight:700;color:var(--green)}a{color:var(--green)}select,input{padding:11px;border:1px solid var(--line);background:var(--paper);border-radius:8px;font:inherit;max-width:100%}.tools{display:flex;gap:12px;flex-wrap:wrap}summary{cursor:pointer;font-weight:600}li{margin:8px 0}.note{padding:12px;background:#eee8d4;font-size:14px}footer{font-size:13px;color:#5a6c65}@media(max-width:700px){.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr;gap:8px}.row{display:block}.badge{display:inline-block;margin:10px 0}h1{font-size:29px}}</style><main>'''
    page+=f'''<header><span class="eyebrow">Rendition Pilot · Read-only feasibility experiment</span><h1>Lubbock County DBA → BPP account comparison</h1><p>Recording-date search: October 19–28, 2026. Retrieved <strong>{s['details_retrieved']} of {s['reported_total']} reported filings</strong>: {s['filing_types'].get('ASSUMED NAME',0)} assumed names and {s['filing_types'].get('ASSUMED NAME ABANDONMENT',0)} abandonments.</p><div class="notice">Public detail pages can supply full names and business addresses. These are computer-generated suggestions for appraisal review. No accounts, queue items, or appraiser decisions were changed. Daily collection is not enabled.</div><div class="stats">{''.join('<div class="stat"><strong>'+str(v)+'</strong><span>'+label+'</span></div>' for label,v in stats)}</div><p><strong>Coverage limits:</strong> no separate mailing addresses were shown. Both abandonments lack business addresses. Document images are available at the Clerk’s office. The latest completed CAD import contains {s['cad_export']['row_count']:,} records and was imported October 23; its export as-of date was not supplied. An unmatched filing does not prove an account is missing today.</p><p><a href="filings.csv">Download comparison CSV</a> · <a href="results.json">Download full evidence JSON</a></p><div class="tools"><input id="search" aria-label="Search results" placeholder="Search business, owner or account"><select id="status" aria-label="Filter result type"><option value="">All {s['details_retrieved']} filings</option><option value="PROBABLE_EXISTING_ACCOUNT">Strong account leads</option><option value="NEEDS_REVIEW">Needs review</option><option value="ABANDONMENT_LEAD">Abandonments</option><option value="NO_RELIABLE_MATCH">No reliable match</option></select><span id="count" aria-live="polite"></span></div></header>'''
    page+=''.join(cards)+'''<footer>Original filing labels and spellings are preserved. Owner-only and address-only suggestions require investigation. A filing does not prove a business opened; abandonment does not prove it closed. This bounded browser-assisted experiment does not establish permission or reliability for unattended collection.</footer></main><script>
const input=document.getElementById('search'),filter=document.getElementById('status');function render(){let n=0;for(const card of document.querySelectorAll('article')){card.hidden=!!((filter.value&&card.dataset.status!==filter.value)||!card.textContent.toLowerCase().includes(input.value.toLowerCase()));if(!card.hidden)n++;}document.getElementById('count').textContent=n+' shown';}input.addEventListener('input',render);filter.addEventListener('change',render);render();</script></html>'''
    (path/'report.html').write_text(page)

if __name__=='__main__':
    import sys
    render(Path(sys.argv[1]))
